import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Privacy Policy","description":"How VERA collects, stores, and uses data.","frontmatter":{"title":"Privacy Policy","description":"How VERA collects, stores, and uses data."},"headers":[],"relativePath":"legal/privacy-policy.md","filePath":"legal/privacy-policy.md"}'),s={name:"legal/privacy-policy.md"};function i(n,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><strong>Last updated:</strong> 2026-05-03<br><strong>Operator:</strong> talktalkmake<br><strong>Contact:</strong> [contact details to be added]</p><hr><h2 id="what-vera-is" tabindex="-1">What VERA is <a class="header-anchor" href="#what-vera-is" aria-label="Permalink to &quot;What VERA is&quot;">​</a></h2><p>VERA is a Slack-based time tracking and project management assistant for professional services agencies. It is deployed on a per-agency (tenant) basis. Each agency&#39;s data is isolated from all other agencies.</p><hr><h2 id="what-data-vera-collects" tabindex="-1">What data VERA collects <a class="header-anchor" href="#what-data-vera-collects" aria-label="Permalink to &quot;What data VERA collects&quot;">​</a></h2><h3 id="data-you-provide-directly" tabindex="-1">Data you provide directly <a class="header-anchor" href="#data-you-provide-directly" aria-label="Permalink to &quot;Data you provide directly&quot;">​</a></h3><p>When you interact with VERA in Slack, the following data is collected and stored:</p><ul><li><strong>Your Slack user ID and display name</strong> — used to identify you within your agency&#39;s workspace. Display names are synced automatically when you message VERA.</li><li><strong>Time entries</strong> — the date, project, task, hours, and notes you submit when logging time.</li><li><strong>Absence records</strong> — PTO requests, sick days, and leave entries you submit.</li><li><strong>Conversation context</strong> — the last 24 hours of your Slack conversation with VERA are stored to provide continuity in multi-turn interactions. Older exchanges are not retained in this context window.</li></ul><h3 id="data-collected-automatically" tabindex="-1">Data collected automatically <a class="header-anchor" href="#data-collected-automatically" aria-label="Permalink to &quot;Data collected automatically&quot;">​</a></h3><ul><li><strong>Message content</strong> — messages sent to VERA in Slack are processed by Anthropic&#39;s Claude API to generate responses. See the Anthropic section below.</li><li><strong>Timestamps</strong> — the date and time of each interaction is recorded.</li></ul><h3 id="data-vera-does-not-collect" tabindex="-1">Data VERA does not collect <a class="header-anchor" href="#data-vera-does-not-collect" aria-label="Permalink to &quot;Data VERA does not collect&quot;">​</a></h3><ul><li>VERA does not collect messages in public Slack channels.</li><li>VERA does not access or store passwords, payment information, or financial account data.</li><li>VERA does not track website visits or use cookies outside the client dashboard.</li></ul><hr><h2 id="how-vera-stores-data" tabindex="-1">How VERA stores data <a class="header-anchor" href="#how-vera-stores-data" aria-label="Permalink to &quot;How VERA stores data&quot;">​</a></h2><p>Each agency&#39;s data is stored in:</p><ul><li><strong>Google Sheets</strong> — the primary operational database for time entries, projects, users, and financial records. Hosted in Google Drive under the agency&#39;s own service account credentials.</li><li><strong>PostgreSQL</strong> (select tenants) — a hosted Postgres database on Railway for agencies enrolled in the Postgres migration programme. This mirrors the Google Sheets data and becomes the primary read source once enabled.</li></ul><p>Data is stored in the agency&#39;s configured timezone. No data is transferred between agencies.</p><hr><h2 id="how-vera-uses-data" tabindex="-1">How VERA uses data <a class="header-anchor" href="#how-vera-uses-data" aria-label="Permalink to &quot;How VERA uses data&quot;">​</a></h2><p>VERA uses collected data exclusively to:</p><ul><li>Respond to your requests in Slack</li><li>Generate morning and evening briefing messages for your team</li><li>Produce project health and financial summaries for Owners and Managers</li><li>Display the client-facing project dashboard (Owners only; no personal data shown)</li></ul><p>VERA does not use your data for advertising, profiling, or any purpose outside the delivery of the time tracking and project management service.</p><hr><h2 id="third-party-processors" tabindex="-1">Third-party processors <a class="header-anchor" href="#third-party-processors" aria-label="Permalink to &quot;Third-party processors&quot;">​</a></h2><h3 id="anthropic-claude-api" tabindex="-1">Anthropic (Claude API) <a class="header-anchor" href="#anthropic-claude-api" aria-label="Permalink to &quot;Anthropic (Claude API)&quot;">​</a></h3><p>Messages sent to VERA are processed by Anthropic&#39;s Claude API to generate responses. Anthropic&#39;s data processing terms apply. VERA operates on the Anthropic Consumer (Pro) plan. For Anthropic&#39;s privacy policy, see: <a href="https://anthropic.com/legal" target="_blank" rel="noreferrer">https://anthropic.com/legal</a></p><h3 id="google-sheets-and-drive" tabindex="-1">Google (Sheets and Drive) <a class="header-anchor" href="#google-sheets-and-drive" aria-label="Permalink to &quot;Google (Sheets and Drive)&quot;">​</a></h3><p>Agency data is stored in Google Sheets and Google Drive under the service account credentials provided by the agency. Google&#39;s data processing terms apply.</p><h3 id="railway-hosting" tabindex="-1">Railway (hosting) <a class="header-anchor" href="#railway-hosting" aria-label="Permalink to &quot;Railway (hosting)&quot;">​</a></h3><p>VERA&#39;s application server and Postgres database are hosted on Railway. Railway&#39;s privacy policy applies to infrastructure-level data handling.</p><h3 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h3><p>VERA uses Slack&#39;s Socket Mode API to send and receive messages. Slack&#39;s privacy policy applies to all message content.</p><hr><h2 id="data-retention" tabindex="-1">Data retention <a class="header-anchor" href="#data-retention" aria-label="Permalink to &quot;Data retention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data type</th><th>Retention</th></tr></thead><tbody><tr><td>Time entries</td><td>Indefinite (no automatic deletion; deleted on request)</td></tr><tr><td>Conversation context</td><td>24-hour rolling window</td></tr><tr><td>Absence records</td><td>Indefinite</td></tr><tr><td>User identity</td><td>Active while the Slack workspace is connected</td></tr></tbody></table><hr><h2 id="your-rights" tabindex="-1">Your rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to &quot;Your rights&quot;">​</a></h2><p>You may request access to, correction of, or deletion of your personal data by contacting your agency&#39;s VERA administrator. VERA administrators may contact talktalkmake to arrange data exports or deletions.</p><hr><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to this policy&quot;">​</a></h2><p>This policy may be updated from time to time. The &quot;Last updated&quot; date at the top of this page reflects when the policy was last revised. Continued use of VERA after a change constitutes acceptance of the updated policy.</p>',43)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
